namespace CheckoutPricing.Domain;

public static class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromPayableCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressCents(tier) : StandardCents(payableTotalCents, tier);

    private static int ExpressCents(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardCents(int payableTotalCents, LoyaltyTier tier) =>
        IsFreeStandard(payableTotalCents, tier) ? 0 : StandardFeeCents;

    private static bool IsFreeStandard(int payableTotalCents, LoyaltyTier tier) =>
        tier is LoyaltyTier.Gold or LoyaltyTier.Platinum
        || payableTotalCents >= FreeStandardFromPayableCents;
}
EOF
